-- Strengthen three existing passive Engineering Control read contracts.
-- Source-reviewed sandy-engineering-control v35; archived bundle SHA-256:
-- 3d8ab5e9e9c296294ec689dd05ce134ff080ea1a6ee8d33b8c826bb1da745b51.
-- Release preflight must independently recheck that deployed source before use.
-- list/get/job_status return after SELECTs, before any write/provider branch.
-- The API forwards the actual owner JWT; backend Controller membership remains
-- independently required. This changes no customer/job data or exposure and
-- verification flags.
BEGIN;
DO $guard$
BEGIN
  PERFORM operation FROM public.sandy_operation_registry
    WHERE operation IN ('engineering.change.get','engineering.change.list','engineering.job.status')
    FOR UPDATE;
  IF (SELECT count(*) FROM public.sandy_operation_registry
    WHERE operation IN ('engineering.change.get','engineering.change.list','engineering.job.status')
      AND domain='engineering' AND handler='sandy-engineering-control'
      AND permission_scope='engineering:read' AND is_mutation=false
      AND input_schema='{"type":"object"}'::jsonb
      AND output_schema='{"type":"object"}'::jsonb
      AND description IS NULL AND error_contract='{}'::jsonb) <> 3 THEN
    RAISE EXCEPTION 'Engineering read contract drift; inspect and reconcile before applying';
  END IF;
END $guard$;
WITH contracts(operation,description,input_schema,output_schema) AS (VALUES
  ('engineering.change.get','Read an existing engineering change and related records; events are limited to the newest 200. Passive owner-only API contract v1.0.0; no approval, provider call or state transition.','{"type":"object","required":["change_id"],"properties":{"change_id":{"type":"string","format":"uuid"}},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","change","events","artifacts","tests","rollbacks"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"change":{"type":"object","required":["id","title","status","risk","created_at","updated_at","verified_at","problem","expected_behavior","scope","regression_rules","acceptance_criteria","requested_by","idempotency_key","change_purpose","feature_improvement"],"properties":{"id":{"type":"string","format":"uuid"},"title":{"type":"string"},"status":{"type":"string"},"risk":{"type":"string"},"created_at":{"type":"string","format":"date-time"},"updated_at":{"type":"string","format":"date-time"},"verified_at":{"type":["string","null"],"format":"date-time"},"problem":{"type":"string"},"expected_behavior":{"type":"string"},"scope":{},"regression_rules":{},"acceptance_criteria":{},"requested_by":{"type":"string","format":"uuid"},"idempotency_key":{"type":["string","null"]},"change_purpose":{"type":["string","null"]},"feature_improvement":{"type":["string","null"]}},"additionalProperties":true},"events":{"type":"array","items":{"type":"object","required":["id","change_id","event_type","actor","detail","occurred_at"],"properties":{"id":{"type":"integer","minimum":1,"maximum":9007199254740991},"change_id":{"type":"string","format":"uuid"},"event_type":{"type":"string"},"actor":{"type":["string","null"],"format":"uuid"},"detail":{},"occurred_at":{"type":"string","format":"date-time"}},"additionalProperties":true},"maxItems":200},"artifacts":{"type":"array","items":{"type":"object","required":["id","change_id","artifact_type","target","before_ref","after_ref","rollback_strategy","rollback_notes","metadata","created_at"],"properties":{"id":{"type":"string","format":"uuid"},"change_id":{"type":"string","format":"uuid"},"artifact_type":{"type":"string"},"target":{"type":"string"},"before_ref":{"type":["string","null"]},"after_ref":{"type":["string","null"]},"rollback_strategy":{"type":"string"},"rollback_notes":{"type":["string","null"]},"metadata":{},"created_at":{"type":"string","format":"date-time"}},"additionalProperties":true}},"tests":{"type":"array","items":{"type":"object","required":["id","change_id","test_name","outcome","evidence","checked_at","created_at"],"properties":{"id":{"type":"string","format":"uuid"},"change_id":{"type":"string","format":"uuid"},"test_name":{"type":"string"},"outcome":{"type":"string"},"evidence":{},"checked_at":{"type":["string","null"],"format":"date-time"},"created_at":{"type":"string","format":"date-time"}},"additionalProperties":true}},"rollbacks":{"type":"array","items":{"type":"object","required":["id","change_id","requested_by","reason","status","plan","created_at","updated_at"],"properties":{"id":{"type":"string","format":"uuid"},"change_id":{"type":"string","format":"uuid"},"requested_by":{"type":"string","format":"uuid"},"reason":{"type":"string"},"status":{"type":"string"},"plan":{},"created_at":{"type":"string","format":"date-time"},"updated_at":{"type":"string","format":"date-time"}},"additionalProperties":true}}},"additionalProperties":false}'::jsonb),
  ('engineering.change.list','Read up to the newest 100 engineering-change summaries. Passive owner-only API contract v1.0.0; fixed backend limit, no pagination or state transition.','{"type":"object","required":[],"properties":{},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","changes"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"changes":{"type":"array","items":{"type":"object","required":["id","title","status","risk","created_at","updated_at","verified_at"],"properties":{"id":{"type":"string","format":"uuid"},"title":{"type":"string"},"status":{"type":"string"},"risk":{"type":"string"},"created_at":{"type":"string","format":"date-time"},"updated_at":{"type":"string","format":"date-time"},"verified_at":{"type":["string","null"],"format":"date-time"}},"additionalProperties":true},"maxItems":100}},"additionalProperties":false}'::jsonb),
  ('engineering.job.status','Read one existing deployment job linked to the supplied engineering change. Passive owner-only API contract v1.0.0; never approves, executes or reconciles the job.','{"type":"object","required":["change_id","job_id"],"properties":{"change_id":{"type":"string","format":"uuid"},"job_id":{"type":"string","format":"uuid"}},"additionalProperties":false}'::jsonb,'{"type":"object","required":["ok","contract_version","job"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"job":{"type":"object","required":["id","engineering_change_id","created_at","updated_at","requested_by","provider","operation","target","payload","idempotency_key","status","approved_by","approved_at","started_at","finished_at","result","error"],"properties":{"id":{"type":"string","format":"uuid"},"engineering_change_id":{"type":"string","format":"uuid"},"created_at":{"type":"string","format":"date-time"},"updated_at":{"type":"string","format":"date-time"},"requested_by":{"type":"string"},"provider":{"type":"string"},"operation":{"type":"string"},"target":{"type":"string"},"payload":{},"idempotency_key":{"type":"string"},"status":{"type":"string"},"approved_by":{"type":["string","null"]},"approved_at":{"type":["string","null"],"format":"date-time"},"started_at":{"type":["string","null"],"format":"date-time"},"finished_at":{"type":["string","null"],"format":"date-time"},"result":{},"error":{"type":["string","null"]}},"additionalProperties":true}},"additionalProperties":false}'::jsonb)
)
UPDATE public.sandy_operation_registry AS registry SET
  description=contracts.description,
  input_schema=contracts.input_schema,
  output_schema=contracts.output_schema,
  error_contract='{"version":"1.0.0","authorization":"enabled_owner_and_backend_controller_membership","transport_failure":"engineering_read_outcome_unknown","transport_execution_state":"unknown","not_found":["engineering_change_not_found","engineering_job_not_found"],"invalid_response":"engineering_read_invalid_or_unscoped_response","side_effects":false,"source_review":{"function":"sandy-engineering-control","version":35,"bundle_sha256":"3d8ab5e9e9c296294ec689dd05ce134ff080ea1a6ee8d33b8c826bb1da745b51"}}'::jsonb,
  updated_at=now()
FROM contracts WHERE registry.operation=contracts.operation;
-- api_exposed/ui_exposed/ai_exposed/verified/last_verified_at and all existing
-- deployment evidence are intentionally preserved. Registration is not testing.
COMMIT;
